function formatTime(seconds: number) {
  return `${Math.floor(seconds / 60)}:${(seconds % 60).toString().padStart(2, "0")}`;
}

function currentTime() {
  return new Date().toLocaleTimeString("es-ES", { hour: "2-digit", minute: "2-digit" });
}

function formatRemaining(iso: string) {
  const milliseconds = Math.max(0, new Date(iso).getTime() - Date.now());
  const hours = Math.floor(milliseconds / 3_600_000);
  const minutes = Math.floor((milliseconds % 3_600_000) / 60_000);
  return `${hours} h ${minutes.toString().padStart(2, "0")} min`;
}

async function attachmentFromFile(file: File): Promise<LocalAttachment> {
  const base = { id: `attachment-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, name: file.name };
  if (!file.type.startsWith("image/")) return { ...base, kind: file.type === "application/pdf" ? "pdf" : "archivo" };
  try {
    const bitmap = await createImageBitmap(file);
    const maxSide = 1200;
    const scale = Math.min(1, maxSide / Math.max(bitmap.width, bitmap.height));
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.round(bitmap.width * scale));
    canvas.height = Math.max(1, Math.round(bitmap.height * scale));
    const context = canvas.getContext("2d");
    context?.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
    bitmap.close();
    return { ...base, kind: "imagen", dataUrl: canvas.toDataURL("image/jpeg", 0.78) };
  } catch {
    return { ...base, kind: "imagen" };
  }
}

function DictationButton({ onText, label = "Dictar" }: { onText: (text: string) => void; label?: string }) {
  const [listening, setListening] = useState(false);
  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const start = () => {
    const Constructor = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!Constructor) {
      toast.info("El dictado depende del navegador. Puedes usar el dictado del teclado de tu móvil o escribir la información.");
      return;
    }
    if (recognitionRef.current && listening) {
      recognitionRef.current.stop();
      return;
    }
    const recognition = new Constructor();
    recognitionRef.current = recognition;
    recognition.lang = "es-ES";
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.onresult = (event) => {
      const phrase = Array.from(event.results).map((result) => result[0]?.transcript ?? "").join(" ").trim();
      if (phrase) onText(phrase);
    };
    recognition.onerror = () => toast.info("No se pudo usar el micrófono. Puedes escribir o adjuntar una foto o un archivo local.");
    recognition.onend = () => { setListening(false); recognitionRef.current = null; };
    try { recognition.start(); setListening(true); } catch { setListening(false); }
  };
  return <button type="button" onClick={start} aria-pressed={listening} className={`inline-flex items-center gap-2 rounded-xl border px-3 py-2 text-xs font-bold transition-colors ${listening ? "border-[#D9FF2B] bg-[#D9FF2B] text-[#0F3A2D]" : "border-current/20 hover:bg-current/8"}`}><Mic className={`w-3.5 h-3.5 ${listening ? "animate-pulse" : ""}`} />{listening ? "Escuchando… toca para parar" : label}</button>;
}

function LocalAttachmentPicker({ attachment, setAttachment, className = "" }: { attachment: LocalAttachment | null; setAttachment: (attachment: LocalAttachment | null) => void; className?: string }) {
  const pick = async (file: File | null) => {
    if (!file) return;
    setAttachment(await attachmentFromFile(file));
  };
  return <div className={`rounded-xl border border-current/15 p-3 ${className}`}><label className="block text-xs font-bold">Foto, captura, PDF o archivo local<input aria-label="Adjuntar foto, captura, PDF o archivo local" type="file" accept="image/*,.pdf" onChange={(event) => void pick(event.target.files?.[0] ?? null)} className="block mt-2 w-full text-xs file:mr-3 file:rounded-lg file:border-0 file:bg-[#F5F1E7] file:px-3 file:py-2 file:font-bold file:text-[#0F3A2D]" /></label>{attachment ? <div className="flex items-center justify-between gap-3 mt-3 text-xs"><span className="inline-flex items-center gap-1.5 min-w-0"><ImagePlus className="w-3.5 h-3.5 shrink-0" /><span className="truncate"><strong>{attachment.name}</strong> · solo local</span></span><button type="button" onClick={() => setAttachment(null)} className="underline font-bold">Quitar</button></div> : <p className="text-[11px] opacity-70 mt-2">Puedes registrar desde una foto o captura sin escribir el dato. No se sube a Kureva.</p>}</div>;
}

