    if (profile.diagnoses.length) { paragraph(`Condiciones que la persona quiso documentar: ${profile.diagnoses.join(", ")}.`, 21, y, 168); y += 9; }
    if (profile.allergies || profile.surgery || profile.medicines) { paragraph(`Notas personales: ${[profile.allergies && `alergias: ${profile.allergies}`, profile.surgery && `cirugía: ${profile.surgery}`, profile.medicines && `medicación anotada: ${profile.medicines}`].filter(Boolean).join(" · ")}.`, 21, y, 168); y += 9; }
    heading("Registros de esta sesión"); if (!records.length) item("No se registraron mediciones o molestias."); records.forEach((record) => item(`${record.kind}: ${record.value || "sin valor"}${record.note ? ` · ${record.note}` : ""}${record.attachment ? ` · adjunto local: ${record.attachment.name}` : ""} · ${record.createdAt}`));
